import sys
import time
import subprocess
from pathlib import Path

def main():
    if len(sys.argv) != 3:
        print("Usage: python throttled_runner.py <rate_per_second> <jobs_file>", file=sys.stderr)
        sys.exit(1)

    try:
        rate = float(sys.argv[1])
        if rate <= 0:
            print("Rate must be a positive number", file=sys.stderr)
            sys.exit(1)
    except ValueError:
        print("Rate must be a number", file=sys.stderr)
        sys.exit(1)

    jobs_file = sys.argv[2]
    try:
        with open(jobs_file, 'r') as f:
            jobs = [line.strip() for line in f if line.strip()]
    except IOError:
        print(f"Error opening file: {jobs_file}", file=sys.stderr)
        sys.exit(1)

    last_start_time = time.time()
    for job in jobs:
        current_time = time.time()
        elapsed = current_time - last_start_time
        if elapsed < 1.0 / rate:
            time.sleep((1.0 / rate) - elapsed)

        try:
            result = subprocess.run(job, shell=True, check=True, text=True, capture_output=True)
            print(result.returncode)
        except subprocess.CalledProcessError as e:
            print(127)
        except Exception:
            print(127)
        last_start_time = time.time()

if __name__ == "__main__":
    main()
